using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class EmploymentTimelineTests
{
 class Time:TimeProvider{public DateTimeOffset Now=new(2026,11,24,10,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
 class User(bool pay=true):ICurrentUser{public string Email=>"schedule@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>pay || p!=Perm.EmpPay;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static EmploymentTimeline S(AppDbContext d,Time t,bool pay=true){var u=new User(pay);var c=new AppClock(t);return new(d,u,c,new AuditService(d,u,c));}
 static EmploymentChange C(Employee e)=>new(){EmployeeId=e.Id,EffectiveOn=new(2026,12,1),DepartmentId=e.DepartmentId==1?2:1,BranchId=e.BranchId,JobTitleId=e.JobTitleId,ShiftId=e.ShiftId,ManagerId=e.ManagerId,BasicSalary=e.BasicSalary+500,Reason="Future transfer"};
 [Fact]public async Task FutureAssignmentLeavesCurrentStateAndAppliesOnceAtBoundary(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);await s.ScheduleAsync(change);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);Assert.Null(change.AppliedAt);t.Now=new(2026,12,1,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(change.DepartmentId,e.DepartmentId);Assert.NotNull(change.AppliedAt);Assert.Single(await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6 && x.EffectiveFrom==change.EffectiveOn).ToListAsync());await s.ApplyDueAsync();Assert.Single(await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6 && x.EffectiveFrom==change.EffectiveOn).ToListAsync());}
 [Fact]public async Task CancelledScheduleNeverApplies(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);await s.ScheduleAsync(change);await s.CancelAsync(change.Id,"Plan withdrawn");t.Now=new(2026,12,2,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);Assert.Null(change.AppliedAt);}
 [Fact]public async Task NoPayPermissionCannotScheduleSalaryIncrease(){await using var d=await Db();var t=new Time();var e=(await d.Set<Employee>().FindAsync(6))!;var change=C(e);await S(d,t,false).ScheduleAsync(change);Assert.Equal(e.BasicSalary,change.BasicSalary);}
 [Fact]public async Task StatusTransitionIsEffectiveDated(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var change=new EmploymentChange{EmployeeId=6,Kind="Status",Status=EmployeeStatus.Suspended,EffectiveOn=new(2026,12,1),Reason="Status change test"};await s.ScheduleAsync(change);Assert.Equal(EmployeeStatus.Active,e.Status);t.Now=new(2026,12,1,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(EmployeeStatus.Suspended,e.Status);Assert.True(await d.Set<StatusHistory>().AnyAsync(x=>x.EmployeeId==6 && x.At==change.EffectiveOn && x.To==EmployeeStatus.Suspended));}
 [Fact]public async Task PastScheduleAndDuplicatePendingScheduleAreRejected(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var bad=C(e);bad.EffectiveOn=new(2026,11,23);await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(bad));await s.ScheduleAsync(C(e));await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(C(e)));}
 [Fact]public async Task TemporaryTransferHasLinkedReturnAndRestoresOriginalAssignment(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var oldDept=e.DepartmentId;var oldPay=e.BasicSalary;var change=C(e);change.ReturnOn=new(2026,12,10);await s.ScheduleAsync(change);var back=await d.Set<EmploymentChange>().SingleAsync(x=>x.ParentChangeId==change.Id);Assert.Equal(oldDept,back.DepartmentId);Assert.Equal(oldPay,back.BasicSalary);await Assert.ThrowsAsync<DomainException>(()=>s.CancelAsync(back.Id,"Cannot orphan the transfer"));e=(await d.Set<Employee>().FindAsync(6))!;back=await d.Set<EmploymentChange>().SingleAsync(x=>x.ParentChangeId==change.Id);t.Now=new(2026,12,1,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(change.DepartmentId,e.DepartmentId);t.Now=new(2026,12,10,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(oldDept,e.DepartmentId);Assert.Equal(oldPay,e.BasicSalary);Assert.NotNull(back.AppliedAt);Assert.Equal(2,await d.Set<EmployeeAssignment>().CountAsync(x=>x.EmployeeId==6&&x.EffectiveFrom>=new DateTime(2026,12,1)));await s.ApplyDueAsync();Assert.Equal(2,await d.Set<EmployeeAssignment>().CountAsync(x=>x.EmployeeId==6&&x.EffectiveFrom>=new DateTime(2026,12,1)));}
 [Fact]public async Task TemporaryTransferCancellationCancelsReturnAtomically(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);change.ReturnOn=new(2026,12,10);await s.ScheduleAsync(change);await s.CancelAsync(change.Id,"Plan withdrawn");Assert.All(await d.Set<EmploymentChange>().Where(x=>x.EmployeeId==6).ToListAsync(),x=>Assert.True(x.Cancelled));t.Now=new(2026,12,11,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);}
 [Fact]public async Task TemporaryTransferCatchesUpBothBoundariesAfterDowntime(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);change.ReturnOn=new(2026,12,10);await s.ScheduleAsync(change);t.Now=new(2026,12,15,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);Assert.All(await d.Set<EmploymentChange>().Where(x=>x.EmployeeId==6).ToListAsync(),x=>Assert.NotNull(x.AppliedAt));Assert.True(await d.Set<EmployeeAssignment>().AnyAsync(x=>x.EmployeeId==6&&x.EffectiveFrom==new DateTime(2026,12,1)&&x.EffectiveTo==new DateTime(2026,12,10)));}
 [Fact]public async Task ReturnMustFollowAssignmentAndCannotBeAppliedToStatusChange(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var change=C(e);change.ReturnOn=change.EffectiveOn;await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(change));await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(new(){EmployeeId=6,Kind="Status",Status=EmployeeStatus.Suspended,EffectiveOn=new(2026,12,1),ReturnOn=new(2026,12,5),Reason="Invalid status return"}));Assert.Empty(await d.Set<EmploymentChange>().Where(x=>x.EmployeeId==6).ToListAsync());}

 [Fact]public async Task InvalidEmployeeBatchDoesNotBlockUnrelatedDueSchedule(){await using var d=await Db();var t=new Time();var s=S(d,t);var bad=(await d.Set<Employee>().FindAsync(6))!;var good=(await d.Set<Employee>().FindAsync(7))!;await s.ScheduleAsync(new(){EmployeeId=6,Kind="Status",Status=EmployeeStatus.Suspended,EffectiveOn=new(2026,12,1),Reason="Deferred fixture status"});await s.ScheduleAsync(new(){EmployeeId=7,Kind="Status",Status=EmployeeStatus.Suspended,EffectiveOn=new(2026,12,1),Reason="Independent fixture status"});bad.Status=EmployeeStatus.Terminated;await d.SaveAsync();t.Now=new(2026,12,2,10,0,0,TimeSpan.Zero);await Assert.ThrowsAsync<AggregateException>(()=>s.ApplyDueAsync());Assert.Null((await d.Set<EmploymentChange>().SingleAsync(x=>x.EmployeeId==6)).AppliedAt);Assert.NotNull((await d.Set<EmploymentChange>().SingleAsync(x=>x.EmployeeId==7)).AppliedAt);Assert.Equal(EmployeeStatus.Suspended,(await d.Set<Employee>().FindAsync(7))!.Status);}
 [Fact]public async Task FailedTemporaryReturnRollsBackEarlierBoundaryForSameEmployee(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var c=C(e);c.ReturnOn=new(2026,12,10);await s.ScheduleAsync(c);var back=await d.Set<EmploymentChange>().SingleAsync(x=>x.ParentChangeId==c.Id);back.DepartmentId=999999;await d.SaveAsync();t.Now=new(2026,12,15,10,0,0,TimeSpan.Zero);await Assert.ThrowsAsync<AggregateException>(()=>s.ApplyDueAsync());Assert.Equal(old,(await d.Set<Employee>().FindAsync(6))!.DepartmentId);Assert.All(await d.Set<EmploymentChange>().Where(x=>x.EmployeeId==6).ToListAsync(),x=>Assert.Null(x.AppliedAt));Assert.Empty(await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6&&x.EffectiveFrom>=new DateTime(2026,12,1)).ToListAsync());}
}
